import{_ as r,o,c as d,a2 as e}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/ko/git-compare-pane.png",a="/relio/shots/ko/git-merge-pane.png",k=JSON.parse('{"title":"Git과 합치기","description":"","frontmatter":{},"headers":[],"relativePath":"features/git.md","filePath":"features/git.md"}'),n={name:"features/git.md"};function s(l,t,g,h,c,b){return o(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="git과-합치기" tabindex="-1">Git과 합치기 <a class="header-anchor" href="#git과-합치기" aria-label="Permalink to &quot;Git과 합치기&quot;">​</a></h1><p>두 모델 비교와 변경 SQL, Git 이력 패널, 모델 단위 합치기(3방향 병합)와 Git merge driver를 설명합니다.</p><p>저장소 준비부터 따라 하려면 빠른 시작의 <a href="/relio/quick/git">Git으로 함께 쓰기·합치기</a>를 보세요. Relio는 이 모든 기능에서 Git 저장소에 아무것도 쓰지 않습니다.</p><h2 id="저장소-준비" tabindex="-1">저장소 준비 <a class="header-anchor" href="#저장소-준비" aria-label="Permalink to &quot;저장소 준비&quot;">​</a></h2><p>Git 차이를 작게 만드는 정렬 저장(기본 켬)은 <a href="/relio/features/file#정렬해-저장">파일 › 정렬해 저장</a>에 있습니다. 저장소의 <code>.gitattributes</code>에는 줄 끝을 맞추는 한 줄을 넣어 두세요.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.erm text eol=lf merge=relio</span></span></code></pre></div><h2 id="비교·병합-메뉴" tabindex="-1">비교·병합 메뉴 <a class="header-anchor" href="#비교·병합-메뉴" aria-label="Permalink to &quot;비교·병합 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>하는 일</th></tr></thead><tbody><tr><td>파일 › 비교·병합 ▸ › 두 파일 비교…</td><td>파일 A(이전)와 B(이후)를 골라 비교합니다.</td></tr><tr><td>파일 › 비교·병합 ▸ › 저장된 파일과 비교</td><td>지금 문서의 저장하지 않은 변경을 디스크의 파일과 비교합니다.</td></tr><tr><td>파일 › 비교·병합 ▸ › 다른 파일과 비교…</td><td>고른 파일(A)과 열린 문서(B)를 비교합니다.</td></tr><tr><td>파일 › 비교·병합 ▸ › Git 병합 충돌 풀기…</td><td>Git 병합 충돌 상태인 파일을 모델 단위로 풉니다.</td></tr><tr><td>파일 › 비교·병합 ▸ › 다른 브랜치 버전과 합치기…</td><td>다른 브랜치의 같은 파일과 합칩니다.</td></tr><tr><td>파일 › Git 이력</td><td>이 파일의 Git 이력 패널을 엽니다. 상태 표시줄의 브랜치 이름을 눌러도 됩니다.</td></tr></tbody></table><h2 id="비교-화면" tabindex="-1">비교 화면 <a class="header-anchor" href="#비교-화면" aria-label="Permalink to &quot;비교 화면&quot;">​</a></h2><p>비교는 읽기 전용 탭으로 열립니다. 테이블·컬럼·관계를 이름과 번호로 짝지어, 이름이 바뀐 것은 유사도로 추정합니다.</p><ul><li><strong>변경 목록</strong> — 추가됨 · 삭제됨 · 변경됨 · 이름 변경 · 이동 · 속성 변경을 보여 줍니다. 항목을 펼치면 필드마다 <strong>전</strong> · <strong>후</strong> 값이 보입니다. 추정으로 짝지은 항목에는 &quot;(추정)&quot;이 붙습니다.</li><li><strong>묶음: 테이블별 / 종류별</strong> — 변경 목록을 테이블마다 또는 변경 종류마다 묶습니다(<kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>G</kbd>). Markdown 내보내기·복사도 이 방식을 따릅니다.</li><li><strong>필터</strong> — 구조 · 문서 · 배치 · 설정으로 볼 변경을 고르고, <strong>이름 검색</strong>, <strong>추정만</strong>(이름 변경을 유사도로 추정한 항목만)으로 거릅니다.</li><li><strong>캔버스에 보일 쪽</strong> — <strong>A 보기</strong> · <strong>B 보기</strong>. <strong>나머지 흐리게</strong>를 켜면 바뀌지 않은 것을 흐리게 그립니다.</li><li><strong>A⇄B 바꾸기</strong>로 방향을 바꾸고, <strong>다시 비교</strong>로 양쪽을 다시 읽습니다.</li><li><strong>A 열기</strong> · <strong>B 열기</strong> — 고치려면 원래 파일을 엽니다.</li><li><strong>내보내기 ▾</strong> — <strong>Markdown…</strong> · <strong>CSV…</strong> · <strong>JSON…</strong>(필터와 관계없이 전부) · <strong>복사(Markdown)</strong> · <strong>변경 SQL 만들기…</strong>. Markdown·CSV는 지금 필터를 따릅니다.</li><li>두 모델이 같으면 &quot;두 모델은 같습니다&quot;가 나옵니다.</li></ul><h3 id="캔버스의-변경-표시" tabindex="-1">캔버스의 변경 표시 <a class="header-anchor" href="#캔버스의-변경-표시" aria-label="Permalink to &quot;캔버스의 변경 표시&quot;">​</a></h3><ul><li>바뀐 노드는 테두리 색과 왼쪽 위 동그라미(<code>+</code> 추가 · <code>−</code> 삭제 · <code>~</code> 변경)로, 바뀐 컬럼은 그 줄의 바탕색과 줄 끝 기호로 표시합니다.</li><li><strong>B 보기</strong>에서 삭제된 테이블·뷰·노트·이미지는 A에 있던 자리에 회색 점선 상자(<code>− 이름</code>, 취소선)로, 삭제된 컬럼은 그 테이블 아래 점선 줄(<code>− 컬럼명</code>, 취소선)로 보입니다.</li><li><strong>A 보기</strong>에서는 반대로, B에 더해진 것이 점선 상자·점선 줄(<code>+ 이름</code>)로 보입니다.</li><li>점선 상자나 줄을 누르면 변경 목록에서 그 항목을 고릅니다.</li></ul><h3 id="변경-목록-키" tabindex="-1">변경 목록 키 <a class="header-anchor" href="#변경-목록-키" aria-label="Permalink to &quot;변경 목록 키&quot;">​</a></h3><table tabindex="0"><thead><tr><th>키</th><th>하는 일</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd></td><td>항목 사이 이동</td></tr><tr><td><kbd>→</kbd> / <kbd>←</kbd></td><td>고른 항목 펼치기 / 접기</td></tr><tr><td><kbd>Enter</kbd></td><td>고른 항목을 캔버스에서 보여 줍니다.</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>C</kbd></td><td>고른 변경을 Markdown으로 복사</td></tr></tbody></table><figure class="shot" data-scene="git-compare-pane"><img src="'+i+'" alt="비교 화면 — 테이블별로 묶은 변경 목록과 B 쪽 캔버스" loading="lazy"><figcaption>비교 화면 — 테이블별로 묶은 변경 목록과 B 쪽 캔버스</figcaption></figure><h2 id="변경-sql-만들기" tabindex="-1">변경 SQL 만들기 <a class="header-anchor" href="#변경-sql-만들기" aria-label="Permalink to &quot;변경 SQL 만들기&quot;">​</a></h2><p>비교 화면의 내보내기 ▾ › **변경 SQL 만들기…**는 A 구조의 DB를 B 구조로 바꾸는 SQL(ALTER 등)을 만듭니다. PostgreSQL · MySQL · MariaDB · SQL Server · Oracle을 지원합니다. Relio는 이 SQL을 만들기만 하고 실행하지 않습니다.</p><table tabindex="0"><thead><tr><th>칸</th><th>설명</th></tr></thead><tbody><tr><td>대상 DB · 대상 제품 · 대상 버전</td><td>SQL을 만들 DB.</td></tr><tr><td>방향 바꾸기</td><td>A와 B를 바꿔 반대 방향 SQL을 만듭니다.</td></tr><tr><td>이름 변경으로 추정한 항목</td><td>확실하지 않은 이름 변경을 어떻게 쓸지: <strong>주석으로 남김</strong>(기본) · <strong>이름 변경으로</strong> · <strong>삭제+추가로</strong></td></tr><tr><td>DB 주석 반영</td><td>주석 변경도 SQL로 만듭니다.</td></tr><tr><td>한 트랜잭션으로 감싸기</td><td>스크립트 전체를 트랜잭션 하나로 감쌉니다(지원하는 DB에서).</td></tr><tr><td>파일 이름</td><td><strong>기본 이름</strong> 또는 <strong>Flyway 이름</strong></td></tr></tbody></table><ul><li><strong>SQL</strong> 탭에 스크립트가, <strong>경고</strong> 탭에 위험한 변경이 보입니다. 위험한 변경은 <strong>파괴</strong>(데이터가 사라짐) · <strong>데이터 의존</strong>(데이터에 따라 실패할 수 있음) · <strong>호환 깨짐</strong>(바깥 프로그램이 깨질 수 있음)으로 나눠 알립니다.</li><li>&quot;주석으로 남김&quot;을 고르면 확실하지 않은 자리를 주석으로 쓰고 &quot;확인 필요 n곳 — 고르기 전에는 결과가 B와 다릅니다&quot;를 알립니다.</li><li>만들 수 없는 변경은 스크립트 끝 &quot;수동 처리 필요&quot; 목록으로 알려 줍니다.</li><li><strong>저장…</strong> · <strong>복사</strong>로 내보냅니다. 명령줄은 <code>relio diff --format sql</code>입니다.</li></ul><div class="warning custom-block"><p class="custom-block-title">주의</p><p>변경 SQL은 실행 전에 꼭 읽어 보고, &quot;수동 처리 필요&quot; 목록을 처리한 뒤 DB 도구에서 직접 실행하세요. 운영 DB라면 백업부터 하세요.</p></div><h2 id="git-이력" tabindex="-1">Git 이력 <a class="header-anchor" href="#git-이력" aria-label="Permalink to &quot;Git 이력&quot;">​</a></h2><p>파일 › Git 이력(또는 상태 표시줄의 브랜치 이름)으로 오른쪽에 패널이 열립니다.</p><ul><li>맨 위 <strong>이력을 시작할 브랜치·태그</strong>에서 지금 브랜치나 다른 브랜치·태그를 고릅니다. <strong>새로 고침</strong>으로 다시 읽습니다.</li><li><strong>최신 커밋 카드</strong> — 바로 앞 버전과 비교한 요약(<code>테이블 +1 · 컬럼 +2 ~3</code>)을 보여 줍니다. 카드를 누르면 직전 버전과 비교하고, 칩을 누르면 그 종류를 펼친 채 엽니다. 병합 커밋은 첫 번째 부모와 비교합니다.</li><li>커밋 목록 아래 단추: <ul><li><strong>직전 버전과 비교</strong> — A = 바로 앞 버전, B = 고른 버전.</li><li><strong>현재와 비교</strong> — A = 고른 버전, B = 열린 문서. 줄을 두 번 눌러도 됩니다.</li><li><strong>두 버전 비교</strong> — <kbd>Ctrl</kbd>을 누른 채 두 줄을 고릅니다(오래된 쪽이 A).</li><li><strong>이 버전 열기</strong> — 그 버전을 읽기 전용 탭으로 엽니다(다른 이름으로 저장은 됩니다).</li></ul></li><li>파일 이름이 바뀐 이력도 따라갑니다. 저장소 밖 파일, 저장하지 않은 문서, 읽기 전용 탭에는 이력이 없다고 알려 줍니다.</li></ul><h2 id="합치기" tabindex="-1">합치기 <a class="header-anchor" href="#합치기" aria-label="Permalink to &quot;합치기&quot;">​</a></h2><p>같은 <code>.erm</code>을 두 곳에서 고쳤을 때 줄 단위가 아니라 모델 단위(테이블·컬럼·관계·필드)로 합칩니다. 양쪽이 각자 더한 것은 충돌 없이 합치고, 같은 칸을 다르게 고친 것만 고르면 됩니다. 결과는 늘 올바른 <code>.erm</code>입니다.</p><h3 id="여는-길" tabindex="-1">여는 길 <a class="header-anchor" href="#여는-길" aria-label="Permalink to &quot;여는 길&quot;">​</a></h3><ul><li><strong>바깥에서 파일이 바뀌었을 때</strong> — 창으로 돌아올 때의 알림이나 저장 직전 확인 창에서 <strong>합치기…</strong></li><li><strong>Git 병합 충돌</strong> — 파일 › 비교·병합 ▸ › Git 병합 충돌 풀기…. 충돌 표시(<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>)가 남은 파일을 열려고 해도 안내 창에서 바로 풉니다. 충돌 상태인 파일을 열면 위에 &quot;Git 병합 충돌이 남아 있습니다&quot; 띠와 <strong>풀기</strong> 단추가 나옵니다.</li><li><strong>다른 브랜치와</strong> — 파일 › 비교·병합 ▸ › 다른 브랜치 버전과 합치기…에서 합칠 버전을 고릅니다. 저장소는 바뀌지 않고 열린 문서만 바뀝니다.</li><li><strong>줄 단위로 망가진 파일</strong> — &quot;이 파일은 줄 단위 병합으로 망가졌을 수 있습니다&quot; 띠의 <strong>병합을 모델 단위로 다시 하기</strong>.</li></ul><h3 id="합치기-탭" tabindex="-1">합치기 탭 <a class="header-anchor" href="#합치기-탭" aria-label="Permalink to &quot;합치기 탭&quot;">​</a></h3><ul><li>목록은 <strong>충돌</strong> · <strong>확인 필요</strong> · <strong>자동</strong>(자동 — 내 쪽만 · 자동 — 바깥 쪽만 · 자동 — 양쪽 같음)으로 나뉩니다. 위에 자동 n · 충돌 n(남음 n) · 확인 n이 보입니다.</li><li>항목을 펼치면 필드마다 <strong>바탕</strong> · <strong>내 쪽</strong> · <strong>바깥 쪽</strong> 값이 보이고 줄마다 고릅니다.</li><li><strong>캔버스에 보일 쪽</strong> — 결과 · 내 쪽 · 바깥 쪽. 충돌한 객체를 강조하고, <strong>나머지 흐리게</strong>로 관계없는 것을 흐립니다.</li><li><strong>이름 검색</strong>, <strong>충돌만</strong>으로 거르고, <strong>남은 충돌 모두 내 것</strong> · <strong>남은 충돌 모두 바깥 것</strong>으로 한 번에 고릅니다. <strong>목록 복사</strong>로 항목 목록을 Markdown으로 복사합니다.</li><li>문서나 디스크 파일이 그사이 또 바뀌면 알리고 <strong>다시 합치기</strong>를 권합니다.</li></ul><table tabindex="0"><thead><tr><th>키</th><th>하는 일</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd></td><td>항목 사이 이동</td></tr><tr><td><kbd>1</kbd> · <kbd>2</kbd> · <kbd>3</kbd></td><td>내 쪽 값 · 바깥 쪽 값 · 둘 다</td></tr><tr><td><kbd>F8</kbd> / <kbd>Shift</kbd>+<kbd>F8</kbd></td><td>다음 · 이전 충돌</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Enter</kbd></td><td>적용</td></tr></tbody></table><figure class="shot" data-scene="git-merge-pane"><img src="'+a+'" alt="합치기 탭 — 충돌을 펼쳐 바탕·내 쪽·바깥 쪽 값을 고르는 모습" loading="lazy"><figcaption>합치기 탭 — 충돌을 펼쳐 바탕·내 쪽·바깥 쪽 값을 고르는 모습</figcaption></figure><h3 id="적용" tabindex="-1">적용 <a class="header-anchor" href="#적용" aria-label="Permalink to &quot;적용&quot;">​</a></h3><p>남은 충돌이 0이면 <strong>적용</strong>으로 문서에 넣습니다. 합친 결과 전체가 되돌리기(<kbd>Ctrl</kbd>+<kbd>Z</kbd>) 한 번으로 돌아갑니다. 파일에 쓰려면 저장합니다. <strong>취소</strong>는 합치지 않고 탭을 닫습니다(문서는 그대로).</p><p>Git 충돌을 푼 뒤 저장하면 상태 표시줄에 &quot;충돌을 풀었습니다 — Git에 알리려면 git add …을(를) 실행하세요&quot;가 나옵니다. <code>git add</code>는 직접 실행합니다.</p><h2 id="git-merge-driver" tabindex="-1">Git merge driver <a class="header-anchor" href="#git-merge-driver" aria-label="Permalink to &quot;Git merge driver&quot;">​</a></h2><p>명령줄 <code>relio merge</code>를 Git merge driver로 등록하면 <code>git merge</code>·<code>git rebase</code>가 <code>.erm</code>을 자동으로 모델 단위로 합칩니다. 충돌이 남으면 Git은 그 파일을 충돌로 남기고, Relio에서 열어 Git 병합 충돌 풀기…로 마저 풉니다. 등록 방법과 확인 방법은 <a href="/relio/features/cli#git-merge-driver">명령줄 › Git merge driver</a>에 있습니다.</p>',37)])])}const p=r(n,[["render",s]]);export{k as __pageData,p as default};
